t.t-value:
request and (
                   (rl_order_obj and (rl_order_obj.sudo()._rl_portal_brand() if rl_order_obj._name == 'sale.order' else rl_order_obj.sudo()._rl_doc_brand()) == 'cr')
                   or (not rl_order_obj and request.session.get('rl_web_brand') == 'cr' and any(
                       request.httprequest.path.startswith(prefix)
                       for prefix in ('/my', '/shop', '/payment', '/web/login', '/web/signup', '/web/reset_password')
                   ))
               )

t.script:
document.addEventListener('DOMContentLoaded', function () {
    document.title = document.title.replace(/\s*\|[^|]*$/, ' | Christian Revive');
    // Send "back to shop" links to the Christian Revive
    // store instead of the Lifestyle shop.
    document.querySelectorAll('a[href="/shop"]').forEach(function (link) {
        link.setAttribute('href', '/christianrevive');
    });
});
